def transform(grid):
    # Preserve the top pattern; fill its empty cells from the aligned lower panels.
    out = [row[:] for row in grid[:3]]
    for r in range(3):
        for c in range(6):
            if out[r][c] == 0:
                for rr in range(3, 12, 3):
                    if grid[rr + r][c] != 0:
                        out[r][c] = grid[rr + r][c]
                        break
    return out
